const DEFAULT_TEAM=9;   // 처음 고른 상태: 위상이 가장 낮은 구단 (작은 구단의 기적)
function postStageShort(){const P=S.post;if(!P||P.s!==S.season||P.done)return '포스트시즌';const D=SL.BAL.POST[P.stage];const c=P.ser[P.stage];return `${D.short} ${c?c.w[0]+c.w[1]+1:1}차전`;}
function postStageName(){const P=S.post;if(!P||P.s!==S.season)return '포스트시즌';return SL.BAL.POST[Math.min(P.stage,SL.BAL.POST.length-1)].name;}
function loanChip(p){if(!p.loan)return '';const f=S.teams[p.loan.from];return `<span class="chip o">임대 중${f?' · 원소속 '+esc(f.name):''}</span>`;}
function expTag(p){if(p.teamId!==S.userTeamId||!p.contract)return '';if(p.contract.years<=0)return '<span class="chip o">계약 만료</span> ';if(S.phase==='season'&&p.contract.years<=1)return '<span class="chip o">시즌 후 FA</span> ';return '';}
let mineP=false,ncap=[];

// ---------- 표로 보기 (EA 2011 드래프트 표처럼 한 줄 한 선수) — 카드 보기와 전환, 선택은 기기에 기억 ----------
function listMode(){if(ui.lmode==null){try{ui.lmode=localStorage.getItem('sl_lmode')||'table';}catch(e){ui.lmode='table';}}return ui.lmode;}
function lmBtn(){const t=listMode()==='table';return `<button class="sm ghost lmbtn" onclick="UI.lmode()" aria-label="목록 보기 방식 바꾸기">${t?'카드로 보기':'표로 보기'}</button>`;}
function ptable(ps,cols,empty){if(!ps.length)return `<div class="muted">${empty||'없습니다.'}</div>`;return `<div class="ptw"><table class="ptab"><thead><tr>${cols.map(c=>`<th class="${c.c||''}">${c.h}</th>`).join('')}</tr></thead><tbody>${ps.map(p=>`<tr onclick="UI.openPlayer(${p.id})">${cols.map(c=>`<td class="${c.c||''}">${c.v(p)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
const TCOL={name:{h:'이름',c:'tn',v:p=>`${esc(p.name)}`},pos:{h:'위치',c:'tc',v:p=>p.pos},age:{h:'나이',c:'tc',v:p=>p.age},
  ovr:{h:'오버',c:'to',v:p=>{const o=SL.calcOvr(p);return `<span class="gl ${SL.gradeOf(o)}">${SL.gradeOf(o)}</span>${Math.round(o)}`;}},
  pot:{h:'잠재',c:'tc',v:p=>SL.potText(p)}};
function commits(ut,exceptPid){const pd=SL.draftPending?SL.draftPending():[];const da=pd.reduce((s,p)=>s+(p.drafted&&p.drafted.ask||0),0);const negs=(S.market.negs||[]).filter(n=>n.pid!==exceptPid).length;const fa=S.phase==='offseason'?(S.pendingFA||[]).length:0;
  const parts=[];if(pd.length)parts.push(`지명 계약 대기 ${pd.length}명(계약금 ${Ms(da)})`);if(fa)parts.push(`재계약 대기 ${fa}명`);if(negs)parts.push(`다른 협상 ${negs}건`);return {da,parts};}
function moneyLine(extra){const ut=SL.userTeam();return `<div class="mline"><span>구단 자금 <b>${Ms(ut.cash)}</b></span>${extra?`<span>${extra}</span>`:''}</div>`;}
function prow(p,extra){const ovr=SL.calcOvr(p);const r=role(p);
  const sd=SL.seasonDelta(p);const dTag=sd&&sd.d?`<span class="${sd.d>0?'up':'dn'} small">${sd.d>0?'+':''}${sd.d}</span>`:'';
  return `<div class="prow" onclick="UI.openPlayer(${p.id})">${face(p,40)}<div class="grow"><div class="nm">${esc(p.name)} <span class="muted small" style="font-weight:400">${p.pos} · ${p.age}세</span></div><div class="sub">${expTag(p)}${fitWarn(p)}${r?esc(r)+' · ':''}${extra!=null?extra:seasonLine(p)}</div></div><div class="rt"><div class="row" style="gap:5px;justify-content:flex-end">${G(ovr)}<span class="ovr">${Math.round(ovr)}</span>${dTag}</div><div class="muted small">잠재 ${SL.potText(p)}</div></div></div>`;}
function valDelta(p){const sd=SL.seasonDelta(p);if(!sd||sd.v==null||Math.abs(sd.v)<100)return '';return ` <span class="${sd.v>0?'up':'dn'}">${sd.v>0?'+':''}${Ms(sd.v)}</span>`;}
function lgName(t){return t.league==='KR'?'국내':SL.BAL.LEAGUES[t.league].name;}
function standChips(p,t){t=t||(p.teamId!=null?S.teams[p.teamId]:null);if(!t)return '';const ls=SL.leagueStanding(p,SL.leagueKey(t));const role=SL.expectedRole(p,t);
  if(t.isUser){const cur=SL.rosterRole(t,p.id);return `<span class="chip ${ls.cls}">${ls.label}</span> <span class="chip">현재 ${esc(cur.text)}</span> <span class="chip ${role==='주전'?'g':role==='벤치'?'r':''}">실력상 ${role}급</span>${(()=>{const ps=SL.promiseStatus(p);if(!ps)return p.grudge?' <span class="chip r">약속 불이행 서운함</span>':'';return ` <span class="chip o">${ps.kind==='apology'?'사과 후 기회':'주전 약속'} ${ps.pending?'· 다음 시즌부터':`${ps.on}/${ps.n}경기 주전 (${ps.of}경기 중 ${ps.need} 필요)`}${SL.promiseKept(t,p)?'':' · 지금 미기용'}</span>`;})()}`;}
  return `<span class="chip ${ls.cls}">${ls.label}</span> <span class="chip ${p.tier>1&&SL.BAL.FARM[t.league]?'o':role==='주전'?'g':role==='벤치'?'r':''}">${p.tier>1&&SL.BAL.FARM[t.league]?esc(SL.farmKo(t.league,p.tier))+' · 콜업 대기':esc(t.name.split(' ').pop())+' '+role}</span>`;}
// ----- 코치진 -----
function coachFace(c,size){return face({id:900000+c.id,nat:c.nat,age:Math.max(40,c.age),teamId:null},size);}
function coachRow(c,mine){const ST=SL.BAL.STAFF;const g=SL.gradeOf(c.rating);const tm=mine?null:SL.coachTerms(c);const yrs=ui.coachYears||2;
  const sal=mine?(c.years>0?c.salary:SL.renewDemand(c)):tm.salary;
  let act='';if(mine){if(c.years<=0)act=S.phase==='offseason'?`<button class="sm go" onclick="UI.renewCoach(${c.id})">재계약 ${yrs}년</button>`:'';
      else if(ui.fireArm===c.id){const sev=SL.severanceOf(c);act=`<button class="sm warn" onclick="UI.fireCoach(${c.id})">해임 확정${sev?' (보상 '+Ms(sev)+')':''}</button>`;}
      else act=`<button class="sm ghost" onclick="UI.armFire(${c.id})">해임</button>`;}
    else act=tm.ok?`<button class="sm go" onclick="UI.hireCoach(${c.id})">${yrs}년 계약</button>`:`<button class="sm" disabled>영입 불가</button>`;
  const stTxt=mine?(c.years>0?`계약 ${c.years}년 남음`:`<span class="due">계약 만료${S.phase==='offseason'?' — 2주차까지 재계약':''}</span>`):(tm.why?`<span class="${tm.ok?'due':'bad'}">${esc(tm.why)}</span>`:'바로 계약 가능');
  return `<div class="prow" style="cursor:default">${coachFace(c,40)}<div class="grow"><div class="nm">${esc(c.name)} <span class="muted small" style="font-weight:400">${mine?'':esc(ST[c.dept].name)+' · '}${c.age}세${c.nat!=='KR'?' · '+SL.NAT_KO[c.nat]:''}</span></div>
    <div class="sub">${esc(c.bio)}${c.trait?` · <span class="chip g">${esc(c.trait)}</span>`:''}</div><div class="sub">연봉 ${Ms(sal)} · ${stTxt}</div></div>
    <div class="rt"><div class="row" style="gap:5px;justify-content:flex-end">${G(c.rating)}<span class="ovr">${c.rating}</span></div><div style="margin-top:6px">${act}</div></div></div>`;}
function renderStaff(ut){const ST=SL.BAL.STAFF;const sm=SL.staffSummary(ut);const staff=ut.staff||[];let h='';
  const active=staff.filter(c=>c.years>0);const expiring=staff.filter(c=>c.years<=0);
  h+=`<div class="stat3"><div><div class="k">코치진</div><div class="v">${active.length}명</div></div><div><div class="k">연간 인건비</div><div class="v">${Ms(SL.staffPay(ut))}</div></div><div><div class="k">계약 만료</div><div class="v ${expiring.length?'due':''}">${expiring.length}명</div></div></div>`;
  h+=`<div class="muted small clamp" style="margin-bottom:0">코치 등급(S~D)과 평점이 높을수록, 같은 부서에 여럿 둘수록 효과가 커집니다(두 번째부터는 효과 체감). 효과는 리그 평균 코치진 대비입니다. 연봉은 경기일마다 나눠 지급됩니다.</div><button class="morebtn" style="margin-bottom:8px" onclick="this.previousElementSibling.classList.toggle('open');this.textContent=this.previousElementSibling.classList.contains('open')?'접기':'자세히'">자세히</button>`;
  for(const d in ST){const x=sm[d];const mine=staff.filter(c=>c.dept===d).sort((a,b)=>b.rating-a.rating);const pos=x.tone==='up',neg=x.tone==='dn';
    h+=`<div class="card">${hd(x.name,`${x.n}/${x.max}명${x.exp?` (만료 ${x.exp})`:''} · ${Ms(x.pay)}/시즌`)}<div class="muted small">${esc(x.what)}</div>
      <div class="row" style="gap:8px;margin:8px 0 4px"><div class="bar grow" title="부서 역량"><i style="width:${Math.min(100,x.P/2.5*100)}%;${neg?'background:var(--red)':''}"></i></div><span class="small ${pos?'up':neg?'dn':'muted'}" style="white-space:nowrap">${esc(x.eff)}</span></div>
      ${mine.map(c=>coachRow(c,true)).join('')||`<div class="muted small" style="padding:6px 0">코치가 없습니다.${x.ref>0?' 리그 평균보다 효과가 떨어집니다.':''}</div>`}
      ${x.n<x.max?`<button class="sm ghost" style="margin-top:6px" onclick="UI.coachMarket('${d}')">${esc(x.name)} 후보 보기</button>`:''}</div>`;}
  const fd=ui.coachDept||'all';const pool=(S.staffPool||[]).filter(c=>fd==='all'||c.dept===fd).sort((a,b)=>b.rating-a.rating);
  h+=`<div class="card" id="coachMarket">${hd('코치 시장','스토브리그마다 새 후보 · 시즌 중에도 영입 가능')}${moneyLine(`코치 인건비 <b>${Ms(SL.staffPay(ut))}</b>/시즌`)}<div class="seg" style="margin-bottom:8px">${[1,2,3].map(y=>`<button class="${(ui.coachYears||2)===y?'on':''}" onclick="UI.coachYears(${y})">계약 ${y}년</button>`).join('')}</div><div class="row" style="margin-bottom:6px"><select aria-label="부서" onchange="UI.coachMarket(this.value)"><option value="all">전체 부서</option>${Object.keys(ST).map(k=>`<option value="${k}" ${fd===k?'selected':''}>${ST[k].name}</option>`).join('')}</select></div>
    <div class="muted small" style="margin-bottom:4px">S급은 약소 구단(위상 22 미만) 제의를 받지 않고, 위상이 낮을수록 상위 등급 코치가 연봉을 더 요구합니다.</div>${pool.map(c=>coachRow(c,false)).join('')||'<div class="muted">후보가 없습니다.</div>'}</div>`;
  return h;}
function hd(t,small){return `<div class="hd"><h3>${t}</h3>${small?`<small>${small}</small>`:''}</div>`;}
// 묶음 탭: 위에는 큰 묶음 3~4개, 묶음 안에 화면이 여럿이면 아래 작은 칩으로 (예전 하위 탭 키는 그대로 → 다른 화면의 바로가기 유지)
function groupTabs(key,groups){const cur=ui.sub[key];let gi=groups.findIndex(g=>g[1].some(s=>s[0]===cur));if(gi<0){gi=0;ui.sub[key]=groups[0][1][0][0];}ui.lastSub=ui.lastSub||{};ui.lastSub[key+gi]=ui.sub[key];
  const top=`<div class="subtabs gtabs">${groups.map((g,i)=>`<button class="${i===gi?'on':''}" onclick="UI.setSub('${key}','${ui.lastSub[key+i]||g[1][0][0]}')">${g[0]}</button>`).join('')}</div>`;
  const ch=groups[gi][1].length>1?`<div class="chiprow">${groups[gi][1].map(s=>`<button class="${s[0]===ui.sub[key]?'on':''}" onclick="UI.setSub('${key}','${s[0]}')">${s[1]}</button>`).join('')}</div>`:'';return top+ch;}
function subtabs(key,items){return `<div class="subtabs">${items.map(i=>`<button class="${ui.sub[key]===i[0]?'on':''}" onclick="UI.setSub('${key}','${i[0]}')">${i[1]}</button>`).join('')}</div>`;}
function decisions(){let n=S.market.offers.length+((S.jobOffers||[]).length);if(SL.draftTurn())n++;if(SL.fdTurn())n++;if(S.phase==='offseason')n+=S.pendingFA.length;return n;}
function bubbles(log,names){return log.map(l=>{const cls=l.who==='me'?'me':l.who==='club'?'club':l.who==='sys'?'sys':'them';const nm=l.who==='me'||l.who==='sys'?'':`<span class="who">${esc(names[l.who]||names.player||'')}</span>`;return `<div class="bub ${cls}">${nm}${esc(l.text)}</div>`;}).join('');}

// ---------- 루트 ----------
// 한 화면 원칙: 화면에 다 안 들어가면 카드들을 타일로 바꾸고, 타일을 누르면 그 카드를 팝업으로 연다 (긴 목록 하나뿐이면 그 카드 안에서만 스크롤)
const CARD_STORE={};
// 안쪽 스크롤 위치 기억: 다시 그려도(체크·필터·저장) 보던 목록 위치를 유지
const SC_MEM={};const scScope=()=>ui.view?('v:'+ui.view.type+':'+(ui.view.pid||'')):(ui.tab+':'+((ui.sub||{})[ui.tab]||''));
let scLast=null;function scSave(){try{if(!scLast)return;const m=SC_MEM[scLast]={};document.querySelectorAll('.scrollcard').forEach((e,i)=>{m[(e.className.includes('tgrid')?'grid':cardTitle(e))+'#'+i]=e.scrollTop;});}catch(e){}}
function scLoad(){try{scLast=scScope();const m=SC_MEM[scLast];if(!m)return;document.querySelectorAll('.scrollcard').forEach((e,i)=>{const v=m[(e.className.includes('tgrid')?'grid':cardTitle(e))+'#'+i];if(v)e.scrollTop=v;});}catch(e){}}
function render(){if(S)scSave();render0();try{fitScreen();scLoad();const m=$('#modal');if(m&&m.dataset.trade){const b=m.querySelector('#tsheet');if(b&&S&&ui.tab==='market'&&ui.sub.market==='trade')b.innerHTML=tradeDeal(SL.userTeam());else closeModal();}}catch(e){if(typeof console!=='undefined')console.error(e);}}
function availH(el){const nav=document.querySelector('.nav');const rp=el.closest('#rpane');const top=rp?el.getBoundingClientRect().top-rp.getBoundingClientRect().top+rp.scrollTop:el.getBoundingClientRect().top+(window.scrollY||0);const pb=parseFloat(getComputedStyle(el).paddingBottom)||0;let res=Math.max(pb,8);for(const bar of document.querySelectorAll('.nav,.actbar')){if(!bar.offsetParent&&getComputedStyle(bar).position!=='fixed')continue;if(!!bar.closest('#rpane')!==!!rp)continue;const ps=getComputedStyle(bar).position;const nb=bar.getBoundingClientRect().height;if(ps==='fixed')res=Math.max(res,nb+8);else if(ps==='sticky'&&!el.contains(bar))res+=nb;}return window.innerHeight-top-res;}
const KEEP_SEL='.today,.decide,.fpc,.result,.report,.keep,.proposal,.asc';
function cardTitle(c){const h=c.querySelector('.hd h3,.ttl,h3');let t=h?h.textContent.trim():'';if(!t){const b=c.querySelector('b,.b');t=b?b.textContent.trim():'자세히';}return t.slice(0,24);}
function cardPreview(c){const tb=c.querySelector('table');if(tb){const rows=[...tb.querySelectorAll('tr')].filter(r=>!r.querySelector('th')).slice(0,3);const t=rows.map(r=>{const x=[...r.cells].map(d=>(d.innerText||d.textContent||'').trim());return /^\d+$/.test(x[0])?x[0]+'위 '+x[1]:x.slice(0,2).join(' ');}).join(' · ');if(t)return t.slice(0,70);}const hd=c.querySelector('.hd');let n=hd?hd.nextElementSibling:c.firstElementChild;let t='';while(n&&t.length<8){t=(n.innerText||n.textContent||'').replace(/\s+/g,' ').trim();n=n.nextElementSibling;}if(t.length<8)t=(c.innerText||'').replace(/\s+/g,' ').trim().slice(cardTitle(c).length);return t.slice(0,70);}
function contentH(root){const top=root.getBoundingClientRect().top;let b=top;for(const e of root.children){const cs=getComputedStyle(e);if(cs.position==='fixed'||cs.position==='absolute'||cs.display==='none')continue;b=Math.max(b,e.getBoundingClientRect().bottom+(parseFloat(cs.marginBottom)||0));}return b-top;}
const overOf=root=>contentH(root)-availH(root);
// 넘치면: ① 카드를 모두 타일로 바꾼 뒤 ② 앞에서부터 들어가는 만큼 카드를 원래대로 되돌리고 ③ 그래도 넘치면 가장 큰 덩어리 안에서만 스크롤
function tileize(root,scope){if(!root)return;const cards=[...root.children].filter(e=>e.classList&&(e.classList.contains('card')||e.classList.contains('story')||e.classList.contains('goalbox'))&&!e.matches(KEEP_SEL)&&!e.querySelector('button.big'));
  if(overOf(root)<=4)return;for(const sel of [':scope>.hero2',':scope>.today',':scope>.phero2','.wboard',':scope>.decide']){const x=root.querySelector(sel+':not(.cmp)');if(x){x.classList.add('cmp');if(overOf(root)<=4)return;}}if(cards.length){
  const only=cards.length===1;
  // 주 작업 카드(화면의 절반 가까이를 차지하는 목록)는 타일로 숨기지 않고 제자리에 둔다 — 넘치면 그 안에서만 스크롤
  const pick=cards.find(c=>c.classList.contains('main'));const main=pick||cards.slice().sort((a,b)=>b.offsetHeight-a.offsetHeight)[0];if(cards.length>1&&(pick||main.offsetHeight>availH(root)*0.45)){cards.splice(cards.indexOf(main),1);main.dataset.main='1';}
  if(only){const c=cards[0];const mh=Math.max(160,c.offsetHeight-overOf(root)-8);c.classList.add('scrollcard');c.style.maxHeight=mh+'px';return;}
  const grid=document.createElement('div');grid.className='tgrid';cards[0].before(grid);const tiles=[];
  cards.forEach((c,i)=>{const title=cardTitle(c);const key=scope+'|'+i+'|'+title;const sm=c.querySelector('.hd small,.tagline');const sub=sm?[...sm.childNodes].filter(n=>n.nodeName!=='BUTTON').map(n=>n.textContent).join('').trim():'';
    const t=document.createElement('button');t.className='tile2';t.innerHTML=`<b>${esc(title)}</b>${sub?`<small>${esc(sub.slice(0,30))}</small>`:''}<span>${esc(cardPreview(c))}</span>`;t.onclick=()=>openCardSheet(key);grid.appendChild(t);CARD_STORE[key]=c;c.remove();tiles.push([t,c,key]);});
  for(const [t,c,key] of tiles){grid.before(c);t.remove();if(overOf(root)>4){c.remove();grid.prepend(t);break;}delete CARD_STORE[key];}
  if(!grid.children.length)grid.remove();}
  for(let k=0;k<3&&overOf(root)>4;k++){const big=[...root.children].filter(e=>e.offsetHeight>(innerHeight<720?130:170)&&(!e.matches(KEEP_SEL)||e.classList.contains('sq'))&&!e.classList.contains('hero2')&&!e.querySelector('button.big')).sort((a,b)=>b.offsetHeight-a.offsetHeight)[0];if(!big)break;big.classList.add('scrollcard');big.style.maxHeight=Math.max(innerHeight<720?120:160,big.offsetHeight-overOf(root)-8)+'px';}
  let ov=overOf(root);if(ov>4){for(const e of [...root.children].filter(e=>e.classList.contains('scrollcard')).sort((a,b)=>b.offsetHeight-a.offsetHeight)){const cut=Math.min(ov+4,e.offsetHeight-(e.dataset.main||e.classList.contains('card')&&!e.classList.contains('tgrid')?120:80));if(cut>0){e.style.maxHeight=(e.offsetHeight-cut)+'px';ov-=cut;}if(ov<=0)break;}}
  // 남는 자리가 있으면 안쪽 스크롤 카드를 다시 늘림 (주 작업 카드 먼저)
  ov=overOf(root);if(ov<-8){for(const e of [...root.children].filter(e=>e.classList.contains('scrollcard')).sort((a,b)=>(b.dataset.main?1:0)-(a.dataset.main?1:0))){const add=Math.min(-ov-6,e.scrollHeight-e.clientHeight);if(add>0){e.style.maxHeight=(e.offsetHeight+add)+'px';ov+=add;}if(ov>=-8)break;}}}
function fold(id,label,n,inner){ui.fold=ui.fold||{};const open=ui.fold[id]!=null?ui.fold[id]:isWide();return `<details class="fbox" ${open?'open':''} ontoggle="UI.foldT('${id}',this.open)"><summary>🔍 ${esc(label)}${n?` <span class="chip g">${n}개 적용</span>`:''}</summary><div class="fin">${inner}</div></details>`;}
function openCardSheet(key){const c=CARD_STORE[key];if(!c)return;modal(`<div class="sheetc">${c.outerHTML}</div>`);const m=$('#modal');if(m)m.dataset.sheet=key;ui.sheetKey=key;}
function fitScreen(){if(!S||S.liveGame)return;for(const k in CARD_STORE)delete CARD_STORE[k];
  const scope=ui.view?('v:'+ui.view.type+':'+(ui.view.pid||'')+':'+(ui.pTab||'')):(ui.tab+':'+(ui.sub[ui.tab]||''));
  const content=document.querySelector('.content');if(content)tileize(content,'c:'+ui.tab+':'+(ui.sub[ui.tab]||''));
  const rp=document.querySelector('#rpane');if(rp){const fc=rp.querySelector('.card');if(fc)tileize(fc.parentElement,'r:'+scope);}
  if(!isWide()&&ui.view){const fc=document.querySelector('#app .card,#app .tgrid');if(fc&&fc.parentElement!==content)tileize(fc.parentElement,'v:'+scope);}
  const m=$('#modal');if(m&&m.dataset.sheet){const key=m.dataset.sheet;const c=CARD_STORE[key];if(c){const box=m.querySelector('.sheetc');if(box)box.innerHTML=c.outerHTML;}else closeModal();}}
function render0(){S=SL.state();const app=$('#app');if(!S){app.innerHTML=renderTitle();return;}
  if(S.liveGame){app.innerHTML=renderGame();const gl=$('#glog');if(gl)gl.scrollTop=gl.scrollHeight;return;}
  let vh='';if(ui.view){const v=ui.view;if(v.type==='player')vh=renderPlayer(v);else if(v.type==='table')vh=renderTable(v);else if(v.type==='offer')vh=renderOffer(v);else if(v.type==='callup')vh=renderCallup(v);else if(v.type==='dispatch')vh=renderDispatch(v);else if(v.type==='loan')vh=renderLoan(v);else if(v.type==='job')vh=renderJob(v);if(!vh)ui.view=null;}
  const scrollChat=()=>{const c=$('#chat');if(c&&c.lastElementChild&&c.lastElementChild.scrollIntoView)try{c.lastElementChild.scrollIntoView({block:'nearest'});}catch(e){}};
  if(isWide()){const rp=$('#rpane');const keep=rp?rp.scrollTop:0;
    app.innerHTML=`<div class="split"><div class="lp">${renderClubBar()}<div class="content gut">${renderTab()}</div>${renderNav()}</div><div class="rp" id="rpane">${vh||rightPaneDefault()}</div></div>`+(S.tutorialDone?'':renderTut());
    const r2=$('#rpane');if(r2&&ui.keepScroll)r2.scrollTop=keep;ui.keepScroll=false;scrollChat();return;}
  if(vh){app.innerHTML=vh;scrollChat();return;}
  app.innerHTML=renderClubBar()+`<div class="content gut">${renderTab()}</div>`+renderNav()+(S.tutorialDone?'':renderTut());
}
function isWide(){try{return window.matchMedia('(min-width: 960px)').matches;}catch(e){return false;}}
