function nw(a){return a.map(x=>`<span class="nw">${esc(x)}</span>`).join(' · ');}
function batToday(b){if(!b||!b.pa)return ['오늘 첫 타석'];const x=[`오늘 ${b.ab}타수 ${b.h}안타`];if(b.hr)x.push(`${b.hr}홈런`);if(b.rbi)x.push(`${b.rbi}타점`);if(b.bb)x.push(`${b.bb}볼넷`);if(b.so)x.push(`${b.so}삼진`);return x;}
function pitToday(b){if(!b)return [];const ip=`${Math.floor(b.pOuts/3)}${b.pOuts%3?'.'+b.pOuts%3:''}이닝`;return [`오늘 ${ip}`,`${b.pH}피안타`,`${b.pSO}삼진`].concat(b.pBB?[`${b.pBB}볼넷`]:[]).concat([`${b.pR}실점`]);}
function batSeason(p){const st=p.cur;if(!st||!st.pa)return ['시즌 기록 없음'];const s=SL.statLine(p,st);const ops=st.ab?((st.h+st.bb)/Math.max(1,st.pa)+(st.h+st.d2+2*st.d3+3*st.hr)/st.ab):0;const b=SL.batLine(st);return [`시즌 타율 ${s.avg}`,`출루율 ${b.obp.toFixed(3).replace(/^0/,'')}`,`${st.hr}홈런`,`OPS ${ops.toFixed(3).replace(/^0/,'')}`];}
function pitSeason(p){const st=p.cur;if(!st||!st.pOuts)return ['시즌 기록 없음'];const s=SL.statLine(p,st);return [`시즌 ERA ${s.era}`,`${s.w}승 ${s.l}패${s.sv?' '+s.sv+'S':''}`,`${s.ip}이닝`];}
function matchupCard(lg,B,P,bb,runners){const pb=lg.box[P.id];const pc=lg.pc[P.id]||0;const lim=P.pos==='SP'?P.attrs.stamina*0.9+30:P.attrs.stamina*0.45+14;const fr=Math.min(1,pc/lim);
  const pos=lg.pos[lg.half][B.id]||B.pos;const A=k=>Math.round(B.attrs[k]),Q=k=>Math.round(P.attrs[k]);
  return `<div class="card mu"><div class="mu2"><div><div class="row" style="gap:8px">${face(B,40)}<div style="min-width:0"><div class="muted small">타자 ${lg.bat[lg.half]+1}번 · ${esc(SL.POS_KO[pos]||pos)}</div><b>${esc(B.name)}</b></div></div>
      <div class="mul b">${nw(batToday(bb))}</div><div class="mul">${nw(batSeason(B))}</div><div class="mul muted">${nw([`컨택 ${A('contact')}`,`파워 ${A('power')}`,`선구 ${A('eye')}`,`주력 ${A('speed')}`])}</div></div>
    <div style="text-align:right"><div class="row" style="gap:8px;justify-content:flex-end"><div style="min-width:0"><div class="muted small">투수 · ${pc}구</div><b>${esc(P.name)}</b></div>${face(P,40)}</div>
      <div class="mul b">${nw(pitToday(pb))}</div><div class="mul">${nw(pitSeason(P))}</div><div class="mul muted">${nw([`${SL.velocity(P)}km`,`구위 ${Q('stuff')}`,`제구 ${Q('control')}`,`변화 ${Q('movement')}`])}</div>
      <div class="small muted" style="margin-top:4px">체력 ${Math.max(0,Math.round(100-fr*100))}%</div><div class="stam" title="투구 수 / 한계"><i style="width:${((1-fr)*100).toFixed(0)}%;background:${fr>0.9?'var(--red)':fr>0.7?'var(--orange)':'var(--green)'}"></i></div></div></div>
    <div class="muted small" style="margin-top:6px">주자: ${runners||'없음'}</div></div>`;}
// 경기 효과음: 홈런(타격음+함성) · 안타(타격음) · 삼진(미트+환호) · 스트라이크(미트) · 볼(약한 미트) · 범타(포구음)
function playSfx(ev,ours){const t=ev.type;if(t==='hr')sfx(ours?'hr':'hit',ours?0.9:0.8);else if(t==='1b'||t==='2b'||t==='3b')sfx('hit',0.85);else if(t==='so')sfx('so',0.75);else if(t==='strike'||t==='whiff')sfx('mitt',0.6);else if(t==='ball')sfx('mitt',0.22);else if(t==='go'||t==='fo'||t==='dp'||t==='sf'||t==='e')sfx('out',0.6);else if(t==='foul')sfx('hit',0.3);}
// ----- 세부 지표 카드 -----
function pctChip(v){if(v==null)return '';const top=v<=50;return `<span class="chip ${v<=20?'g':v>=80?'r':''}">${top?'상위 '+v+'%':'하위 '+(101-v)+'%'}</span>`;}
function advCard(p){const a=SL.advStats(p);if(!a)return '';const f3=x=>x.toFixed(3).replace(/^0/,''),f2=x=>x.toFixed(2),pc=x=>(x*100).toFixed(1)+'%';const P=a.pct||{};const c=a.ctx;
  const tile=(k,v,lgv,pct,tip)=>`<div class="adv"><div class="k">${k}</div><div class="v">${v}</div><div class="l">${lgv!=null?'리그 '+lgv:''}${tip?'<br>'+tip:''}</div>${pct!=null?pctChip(pct):''}</div>`;
  const comp=SL.compName?SL.compName(a.key&&a.key.startsWith('KR')?+a.key.slice(2):a.key):a.key;
  let h=`<div class="card">${hd('세부 지표',`${a.s}시즌${a.live?' · 진행 중':''} · ${esc(comp||'')}`)}`;
  if(a.kind==='bat'){const b=a.b;h+=`<div class="advg">${tile('타율',f3(b.avg),f3(c.avg),P.avg)}${tile('출루율',f3(b.obp),f3(c.obp),P.obp)}${tile('장타율',f3(b.slg),f3(c.slg),P.slg)}${tile('OPS',f3(b.ops),f3(c.obp+c.slg),P.ops)}${tile('OPS+',a.opsPlus,'100')}${tile('wOBA',f3(b.woba),f3(c.woba))}${tile('순장타율(ISO)',f3(b.iso),null,P.iso)}${tile('BABIP',f3(b.babip),f3(c.babip))}${tile('볼넷 비율',pc(b.bbp),pc(c.bbp),P.bbp)}${tile('삼진 비율',pc(b.kp),pc(c.kp),P.kp)}${tile('볼넷/삼진',b.so?f2(b.bb/b.so):'-',null)}${tile('WAR',a.war.war.toFixed(1),null,P.war,`144경기 환산 ${a.war144}`)}</div>
      <div class="small muted" style="margin-top:8px">WAR = (타격 ${a.war.wraa>0?'+':''}${a.war.wraa} · 포지션 ${a.war.posR>0?'+':''}${a.war.posR} · 수비 ${a.war.def>0?'+':''}${a.war.def} · 대체 선수 대비 +${a.war.repl}) 득점 ÷ 10. ${SL.BAL.SEASON_GAMES<100?`시즌이 ${SL.BAL.SEASON_GAMES}경기라 숫자가 작습니다 — 144경기로 환산한 값을 함께 보여 줍니다.`:'144경기 환산값도 함께 보여 줍니다.'}</div>`;}
  else{const q=a.q;h+=`<div class="advg">${tile('평균자책',q.ip?f2(q.era):'-',f2(c.era),P.era)}${tile('ERA+',a.eraPlus||'-','100')}${tile('FIP',f2(a.fip),f2(c.era),P.fip,'수비 영향 뺀 평균자책')}${tile('WHIP',f2(q.whip),f2(c.whip),P.whip)}${tile('9이닝당 삼진',f2(q.k9),f2(c.k9),P.k9)}${tile('9이닝당 볼넷',f2(q.bb9),f2(c.bb9))}${tile('9이닝당 피홈런',f2(q.hr9),f2(c.hr9))}${tile('삼진 비율',pc(q.kp),pc(c.kp),P.kp)}${tile('볼넷 비율',pc(q.bbp),pc(c.bbp),P.bbp)}${tile('WAR',a.war.war.toFixed(1),null,P.war,`144경기 환산 ${a.war144}`)}</div>
      <div class="small muted" style="margin-top:8px">FIP는 삼진·볼넷·피홈런만으로 계산한 평균자책 — 수비·운을 뺀 투수 실력에 가깝습니다. WAR은 FIP를 대체 선수 수준과 비교해 계산합니다.</div>`;}
  if(a.pct)h+=`<div class="small muted" style="margin-top:4px">백분위: 같은 리그 규정 근처 ${a.kind==='bat'?'타자':'투수'} ${a.pct.n}명 중 순위</div>`;
  h+=abilityLink(p,a);return h+`</div>`;}
// 능력치 → 기록 연결 (게임 엔진이 실제로 쓰는 관계)
function abilityLink(p,a){const A=k=>Math.round(p.attrs[k]);const pc=x=>(x*100).toFixed(1)+'%',f3=x=>x.toFixed(3).replace(/^0/,'');const c=a.ctx;const vs=(v,l,hi)=>`<span class="${(hi?v>l:v<l)?'up':'dn'}">${hi?(v>l?'▲':'▼'):(v<l?'▼':'▲')}</span>`;
  const L=a.kind==='bat'?[[`선구 ${A('eye')}`,'볼에 덜 따라가 볼넷↑ 삼진↓',`볼넷 ${pc(a.b.bbp)} ${vs(a.b.bbp,c.bbp,1)}`],[`컨택 ${A('contact')}`,'헛스윙↓ 안타↑',`타율 ${f3(a.b.avg)} ${vs(a.b.avg,c.avg,1)} · 삼진 ${pc(a.b.kp)}`],[`파워 ${A('power')}`,'장타·홈런↑',`순장타율 ${f3(a.b.iso)} · ${a.b.hr}홈런`],[`주력 ${A('speed')}`,'내야안타·추가 진루↑',A('speed')>=70?'땅볼도 내야안타가 잦음':A('speed')>=56?'가끔 내야안타':'내야안타 거의 없음']]
    :[[`구위 ${A('stuff')}`,'헛스윙·삼진↑',`삼진 ${pc(a.q.kp)} ${vs(a.q.kp,c.kp,1)}`],[`제구 ${A('control')}`,'스트라이크↑ 볼넷↓',`볼넷 ${pc(a.q.bbp)} ${vs(a.q.bbp,c.bbp,0)}`],[`변화 ${A('movement')}`,'정타↓ 땅볼↑',`WHIP ${a.q.whip.toFixed(2)} ${vs(a.q.whip,c.whip,0)}`],[`체력 ${A('stamina')}`,'오래 던져도 구위 유지',`${a.q.ip.toFixed(1)}이닝`]];
  return `<div class="b small" style="margin:12px 0 4px">능력치는 이렇게 기록이 됩니다</div>${L.map(x=>`<div class="row sb small" style="padding:4px 0;border-bottom:1px dashed var(--line);gap:8px"><span><b>${x[0]}</b> <span class="muted">${x[1]}</span></span><span style="text-align:right;white-space:nowrap">${x[2]}</span></div>`).join('')}`;}
// ----- 기록실 -----
function renderRecords(ut){const keys=[...new Set(SL.krTeams().map(t=>SL.compKeyOf(t)).concat(ut.league!=='KR'?[SL.compKeyOf(ut)]:[]))].sort();const key=ui.recKey&&keys.includes(ui.recKey)?ui.recKey:SL.compKeyOf(ut);
  const bc=ui.recBat||'ops',pcat=ui.recPit||'era';const BC={avg:'타율',obp:'출루율',ops:'OPS',hr:'홈런',rbi:'타점',war:'WAR'},PC={era:'평균자책',whip:'WHIP',fip:'FIP',pso:'탈삼진',pw:'승리',sv:'세이브',pwar:'WAR'};
  const fmt=(c,v)=>['avg','obp','ops'].includes(c)?v.toFixed(3).replace(/^0/,''):['era','whip','fip'].includes(c)?v.toFixed(2):['war','pwar'].includes(c)?v.toFixed(1):v;
  const nm=k=>k.startsWith('KR')?'한국 프로야구':(SL.BAL.LEAGUES[k]?SL.BAL.LEAGUES[k].name:k);
  let h=`<div class="seg" style="margin-bottom:10px">${keys.map(k=>`<button class="${k===key?'on':''}" onclick="UI.set('recKey','${k}')">${esc(nm(k))}</button>`).join('')}</div>`;
  if(S.phase!=='season')h+=`<div class="muted small" style="margin-bottom:8px">시즌 중 기록입니다. 지난 시즌 기록은 각 선수 상세 → 기록에서 볼 수 있습니다.</div>`;
  const list=(cat,C,setter)=>{const L=SL.leaders(key,cat,10);return `<div class="card">${hd(C[cat],'규정 타석·이닝 적용(비율 기록)')}<div class="row wrap" style="gap:4px;margin-bottom:8px">${Object.keys(C).map(k=>`<button class="sm ${k===cat?'primary':'ghost'}" onclick="UI.set('${setter}','${k}')">${C[k]}</button>`).join('')}</div>
    ${L.map((o,i)=>`<div class="prow" onclick="UI.openPlayer(${o.p.id})"><b style="width:22px">${i+1}</b>${face(o.p,32)}<div class="grow"><div class="nm">${esc(o.p.name)}${o.t&&o.t.isUser?' <span class="chip g">우리</span>':''}</div><div class="sub">${o.t?esc(o.t.name):''} · ${o.p.pos}</div></div><b>${fmt(cat,o.v)}</b></div>`).join('')||'<div class="muted small">아직 기록이 없습니다.</div>'}</div>`;};
  return h+list(bc,BC,'recBat')+list(pcat,PC,'recPit');}
// ----- 홈구장 -----
function parkSvg(pk){const c=pk.dim;const sc=x=>x*0.62;const L=sc(c.l),C=sc(c.c),R=sc(c.r);const cx=100,cy=92;const pt=(a,d)=>[cx+Math.cos(a)*d,cy-Math.sin(a)*d];const A=Math.PI/4,[lx,ly]=pt(Math.PI-A+0.0,L),[rx,ry]=pt(A,R),[mx,my]=pt(Math.PI/2,C);
  return `<svg viewBox="0 0 200 100" width="100%" style="max-width:260px;display:block;margin:0 auto" role="img" aria-label="구장 규격 좌 ${c.l}m 중 ${c.c}m 우 ${c.r}m"><path d="M${cx},${cy} L${lx.toFixed(1)},${ly.toFixed(1)} Q${mx-40},${my-6} ${mx.toFixed(1)},${my.toFixed(1)} Q${mx+40},${my-6} ${rx.toFixed(1)},${ry.toFixed(1)} Z" fill="var(--green-bg)" stroke="var(--green)" stroke-width="${pk.fence?3:1.5}"/><path d="M${cx},${cy} l-18,-18 l18,-18 l18,18 z" fill="#c9a77a" opacity=".7"/>
    <text x="${(lx+8).toFixed(0)}" y="${(ly+14).toFixed(0)}" font-size="9" fill="currentColor">${c.l}m</text><text x="${(mx-10).toFixed(0)}" y="${(my+12).toFixed(0)}" font-size="9" fill="currentColor">${c.c}m</text><text x="${(rx-26).toFixed(0)}" y="${(ry+14).toFixed(0)}" font-size="9" fill="currentColor">${c.r}m</text></svg>`;}
function parkCard(ut){const pk=SL.parkOf(ut);const pct=x=>`${x>1?'+':''}${Math.round((x-1)*100)}%`;const all=SL.krTeams().map(t=>({t,p:SL.parkOf(t)})).sort((a,b)=>b.p.hr-a.p.hr);
  return `<div class="card">${hd('홈구장 · '+esc(pk.name),esc(pk.tag))}${parkSvg(pk)}<div class="stat3" style="margin-top:8px"><div><div class="k">좌·중·우</div><div class="v small2">${pk.dim.l}·${pk.dim.c}·${pk.dim.r}m</div></div><div><div class="k">홈런</div><div class="v small2 ${pk.hr>1?'up':pk.hr<1?'dn':''}">${pct(pk.hr)}</div></div><div><div class="k">2·3루타</div><div class="v small2 ${pk.xb>1?'up':pk.xb<1?'dn':''}">${pct(pk.xb)}</div></div></div>
    <div class="small" style="margin-top:6px">${pk.notes.map(esc).join(' · ')}</div><div class="muted small" style="margin-top:4px">국내 구장 평균 대비입니다. 차이는 아주 작게(홈런 최대 ±8%) — 홈 경기 절반에만 적용되니 선수 영입 때 살짝 참고하는 정도면 됩니다.</div>
    <details style="margin-top:8px"><summary class="small b">국내 10개 구단 구장 비교</summary><div class="tw" style="margin-top:6px"><table><tr><th style="text-align:left">구장</th><th>좌·중·우</th><th>홈런</th><th>2·3루타</th></tr>${all.map(x=>`<tr class="${x.t.isUser?'me':''}"><td style="text-align:left;white-space:nowrap">${esc(x.p.name)} <span class="muted small">${esc(x.t.name.split(' ').pop())}</span></td><td style="white-space:nowrap">${x.p.dim.l}·${x.p.dim.c}·${x.p.dim.r}</td><td class="${x.p.hr>1?'up':x.p.hr<1?'dn':''}">${pct(x.p.hr)}</td><td>${pct(x.p.xb)}</td></tr>`).join('')}</table></div></details></div>`;}
// ----- 시상식 -----
function clubAwardsCard(ut){const L=(S.awardLog||[]).slice().reverse();if(!L.length)return `<div class="card">${hd('우리 구단 역대 수상자')}<div class="muted small">아직 우리 구단 수상자가 없습니다. 시즌이 끝나면 시상식에서 MVP·타이틀·골든글러브를 가립니다.</div></div>`;
  const cnt=k=>L.filter(a=>a.k===k).length;const f=ui.awF||'all';const rows=L.filter(a=>f==='all'||a.k===f);
  const by={};for(const a of L){by[a.pid]=by[a.pid]||{name:a.name,pid:a.pid,n:0};by[a.pid].n++;}const top=Object.values(by).sort((a,b)=>b.n-a.n).slice(0,3);
  return `<div class="card">${hd('우리 구단 역대 수상자',`총 ${L.length}회`)}<div class="row wrap" style="gap:6px;margin-bottom:8px">${[['all','전체'],['mvp',`MVP ${cnt('mvp')}`],['roy',`신인왕 ${cnt('roy')}`],['gg',`골든글러브 ${cnt('gg')}`],['title',`타이틀 ${cnt('title')}`]].map(x=>`<button class="sm ${f===x[0]?'primary':'ghost'}" onclick="UI.set('awF','${x[0]}')">${x[1]}</button>`).join('')}</div>
    ${top.length?`<div class="small muted" style="margin-bottom:6px">최다 수상: ${top.map(x=>`${esc(x.name)} ${x.n}회`).join(' · ')}</div>`:''}
    ${rows.slice(0,60).map(a=>{const p=S.players[a.pid];return `<div class="prow" ${p?`onclick="UI.openPlayer(${a.pid})"`:''}>${p?face(p,34):''}<div class="grow"><div class="nm">${esc(a.name)} <span class="muted small" style="font-weight:400">${a.s}시즌</span></div><div class="sub">🏆 ${esc(a.lab)}${a.vs?' · '+esc(a.vs):''}${p&&p.teamId!==ut.id?(p.retired?' · 은퇴':' · 현 '+esc(S.teams[p.teamId]?S.teams[p.teamId].name:'FA')):''}</div></div></div>`;}).join('')||'<div class="muted small">해당 기록이 없습니다.</div>'}</div>`;}
function awardChips(p){const A=(p.awards||[]).slice().reverse();if(!A.length)return '';const big=A.filter(a=>a.k==='mvp'||a.k==='roy'||a.k==='gg').slice(0,3);const rest=A.length-big.length;
  return `<div style="margin-top:4px">${big.map(a=>`<span class="chip y">🏆 ${a.s}시즌 ${esc(a.lab)}</span>`).join(' ')}${rest>0?` <span class="chip">수상 ${A.length}회</span>`:''}</div>`;}
function awRow(e,lab){const p=S.players[e.pid];const mine=e.tid===S.userTeamId;return `<div class="prow${mine?' mine':''}" ${p?`onclick="UI.closeModal();UI.openPlayer(${e.pid})"`:''}>${p?face(p,38):''}<div class="grow"><span class="dtag">${esc(lab)}</span><div class="nm">${esc(e.name)} ${mine?'<span class="chip g">우리</span>':''}</div><div class="sub">${esc(e.tn)} · ${esc(e.vs||e.line)}</div></div></div>`;}
function ceremonyHtml(s){const A=S.awards&&S.awards[s];if(!A)return '<div class="muted">기록이 없습니다.</div>';const keys=Object.keys(A).sort();const ut=SL.userTeam();const key=ui.cerKey&&A[ui.cerKey]?ui.cerKey:(keys.find(k=>Object.values(A[k]).flat().some(e=>e&&e.tid===ut.id))||keys[0]);const R=A[key];
  const POSN={C:'포수','1B':'1루수','2B':'2루수','3B':'3루수',SS:'유격수',OF:'외야수',DH:'지명타자',P:'투수'};
  const ours=keys.flatMap(k=>{const Rk=A[k];return [Rk.mvp&&{...Rk.mvp,lab:'MVP'},Rk.roy&&{...Rk.roy,lab:'신인왕'},...Rk.titles.map(e=>({...e,lab:SL.AWARD_LABEL[e.k]})),...Rk.gg.map(e=>({...e,lab:'골든글러브 '+(POSN[e.slot]||e.slot)}))].filter(e=>e&&e.tid===ut.id).map(e=>({...e,lab:SL.compLabel(k)+' '+e.lab}));});
  let h=`<div class="ctag">${s}시즌 시상식</div>`;
  if(ours.length){const byP={};for(const e of ours){(byP[e.pid]=byP[e.pid]||{e,labs:[]}).labs.push(e.lab);}h+=`<div class="ourwin"><div class="b" style="font-size:18px;margin-bottom:6px">🎉 축하합니다! 우리 선수 수상 ${ours.length}건</div>${Object.values(byP).map(({e,labs})=>{const p=S.players[e.pid];return `<div class="owrow" ${p?`onclick="UI.closeModal();UI.openPlayer(${e.pid})"`:''}>${p?face(p,64):''}<div><div class="b" style="font-size:17px">${esc(e.name)}</div><div class="small">${labs.map(l=>`<span class="chip y">🏆 ${esc(l)}</span>`).join(' ')}</div><div class="small dim">${esc(e.line||e.vs||'')}</div></div></div>`;}).join('')}</div>`;}
  h+=`<div class="seg" style="margin:8px 0">${keys.map(k=>`<button class="${k===key?'on':''}" onclick="UI.cerKey('${k}',${s})">${esc(SL.compLabel(k))}</button>`).join('')}</div>`;
  if(R.mvp){const p=S.players[R.mvp.pid];h+=`<div class="mvp">${p?face(p,72):''}<div><div class="dtag">${esc(SL.compLabel(key))} 정규 시즌 MVP</div><div class="b" style="font-size:20px">${esc(R.mvp.name)}</div><div class="small">${esc(R.mvp.tn)}</div><div class="small">${esc(R.mvp.line)}</div></div></div>`;}
  if(R.roy)h+=awRow(R.roy,'신인왕');
  h+=`<div class="b" style="margin:10px 0 4px">타이틀</div>${R.titles.map(e=>awRow(e,SL.AWARD_LABEL[e.k])).join('')}`;
  h+=`<div class="b" style="margin:10px 0 4px">골든글러브</div><div class="ggg">${R.gg.map(e=>{const p=S.players[e.pid];return `<div class="gg${e.tid===ut.id?' mine':''}" ${p?`onclick="UI.closeModal();UI.openPlayer(${e.pid})"`:''}>${p?face(p,34):''}<div class="small dim">${POSN[e.slot]||e.slot}</div><div class="b small">${esc(e.name)}</div><div class="small dim">${esc(e.tn.split(' ')[0])}</div></div>`;}).join('')}</div>`;
  return h;}
