    t+=row('현재 종합',ps.map(p=>Math.round(SL.calcOvr(p))),best(p=>Math.round(SL.calcOvr(p)),true));t+=row('예상 잠재',ps.map(p=>`${SL.potText(p)} <span class="muted small">(${SL.confText(p.scout.conf)})</span>`),best(p=>p.scout.est,true));
